import fg from "fast-glob";
import fs from "node:fs";
import micromatch from "micromatch";
import { posix } from "node:path";
import { parseSync } from "oxc-parser";
import { pathToRegexp } from "path-to-regexp";
import { normalizePath } from "vite";
export { pathToRegexp };
export const glob = (path) => fg.sync(path, { absolute: true });
export function cleanPath(src, config) {
    return src
        .slice(config.dir.length)
        .replace(new RegExp(`\.(${(config.extensions ?? []).join("|")})$`), "");
}
export function analyzeModule(src) {
    const result = parseSync(src, fs.readFileSync(src, "utf-8"), { lang: "tsx" });
    const error = result.errors[0];
    if (error)
        throw new SyntaxError(`Failed to parse ${src}:\n${error.codeframe || error.message}`);
    return result.module.staticExports.flatMap(({ entries }) => entries.filter(entry => !entry.isType && entry.exportName.kind !== "None"));
}
export class BaseFileSystemRouter extends EventTarget {
    routes;
    config;
    /**
     *
     * @param {} config
     */
    constructor(config) {
        super();
        this.routes = [];
        this.config = config;
    }
    glob() {
        return (posix.join(fg.convertPathToPattern(this.config.dir), "**/*") +
            `.{${this.config.extensions.join(",")}}`);
    }
    async buildRoutes() {
        for (var src of glob(this.glob())) {
            await this.addRoute(src);
        }
        return this.routes;
    }
    isRoute(src) {
        return Boolean(micromatch(src, this.glob())?.length);
    }
    toPath(src) {
        throw new Error("Not implemented");
    }
    toRoute(src) {
        let path = this.toPath(src);
        if (path === undefined)
            return;
        const exports = analyzeModule(src);
        if (!exports.find(entry => entry.exportName.kind === "Default")) {
            console.warn("No default export", src);
        }
        return {
            $component: {
                src: src,
                pick: ["default", "$css"],
            },
            path,
            // filePath: src
        };
    }
    /**
     * To be attached by vite plugin to the vite dev server
     */
    update = undefined;
    _addRoute(route) {
        const idx = this.routes.findIndex(r => r.path === route.path);
        if (idx >= 0)
            this.routes.splice(idx, 1);
        this.routes.push(route);
        return idx >= 0;
    }
    async addRoute(src) {
        src = normalizePath(src);
        if (this.isRoute(src)) {
            try {
                const route = this.toRoute(src);
                if (route) {
                    this._addRoute(route);
                    this.reload(route.path, "add");
                }
            }
            catch (e) {
                console.error(e);
            }
        }
    }
    reload(route, type) {
        this.dispatchEvent(new CustomEvent("reload", {
            detail: {
                route,
                type,
            },
        }));
    }
    async updateRoute(src_) {
        const src = normalizePath(src_);
        if (this.isRoute(src)) {
            try {
                const route = this.toRoute(src);
                if (route) {
                    const updated = this._addRoute(route);
                    this.reload(route.path, updated ? "update" : "add");
                }
                else {
                    this.removeRoute(src_);
                }
            }
            catch (e) {
                console.error(e);
            }
            // this.update?.();
        }
    }
    removeRoute(src) {
        src = normalizePath(src);
        if (this.isRoute(src)) {
            const path = this.toPath(src);
            if (path === undefined) {
                return;
            }
            const idx = this.routes.findIndex(r => r.path === path);
            if (idx === -1)
                return;
            this.routes.splice(idx, 1);
            this.reload(path, "remove");
        }
    }
    on(type, cb) {
        this.addEventListener(type, cb);
        return () => this.removeEventListener(type, cb);
    }
    buildRoutesPromise;
    async getRoutes() {
        if (!this.buildRoutesPromise) {
            this.buildRoutesPromise = this.buildRoutes();
        }
        await this.buildRoutesPromise;
        return this.routes;
    }
}
